package com.logistics.trackingservice.service;
import io.jsonwebtoken.Claims; import io.jsonwebtoken.Jws; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.io.Decoders; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey;
@Service public class JwtService { @Value("${app.jwt.secret}") private String secret; private SecretKey signingKey() { return Keys.hmacShaKeyFor(Decoders.BASE64.decode(secret)); } public Jws<Claims> parseToken(String token) { return Jwts.parser().verifyWith(signingKey()).build().parseSignedClaims(token); } }
